import heapq

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    # Check if start or goal is out of bounds or is an obstacle
    rows, cols = len(grid), len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Dijkstra's algorithm using a priority queue
    priority_queue = [(0, start[0], start[1])]
    visited = set()
    parent = {}

    while priority_queue:
        distance, row, col = heapq.heappop(priority_queue)

        if (row, col) == goal:
            # Reconstruct the path
            path = []
            while (row, col) != start:
                path.append((row, col))
                row, col = parent[(row, col)]
            path.append(start)
            return path[::-1]

        if (row, col) in visited:
            continue
        visited.add((row, col))

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                if grid[new_row][new_col] == '.' and (new_row, new_col) not in visited:
                    parent[(new_row, new_col)] = (row, col)
                    heapq.heappush(priority_queue, (distance + 1, new_row, new_col))

    # Goal not reachable
    return []

