    priority_queue = [(0, start[0], start[1])]
    visited = set()
    parent = {}

    while priority_queue:
        dist, r, c = heapq.heappop(priority_queue)

        if (r, c) == goal:
            # Reconstruct path
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent[(r, c)]
            path.append(start)
            path.reverse()
            return path

        if (r, c) in visited:
            continue

        visited.add((r, c))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                parent[(nr, nc)] = (r, c)
                heapq.heappush(priority_queue, (dist + 1, nr, nc))

    return []  # Goal not reachable

