def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with priority queue (Dijkstra's alternative using deque for 0-1 BFS)
    # Since weights are non-negative integers up to 100, we can use 0-1 BFS
    # But since weights are not restricted to 0 or 1, we'll use Dijkstra's with a priority queue

    import heapq

    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if u == t:
            return current_dist
        if current_dist > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return -1 if dist[t] == float('inf') else dist[t]

